import { useState, useEffect, useRef } from "react";
import { useAuth } from "../context/AuthContext";
import { db } from "../firebase";
import { doc, getDoc, setDoc } from "firebase/firestore";
import Sidebar from "../components/Sidebar";
import Footer from "../components/Footer";
import toast from "react-hot-toast";

const TOPIC_PHASES = [
  { apt: "Percentages, Ratio & Proportion", dsa: "Arrays" },
  { apt: "Profit & Loss, Averages",         dsa: "Strings" },
  { apt: "Time & Work, Pipes & Cisterns",   dsa: "Searching" },
  { apt: "Time Speed Distance",             dsa: "Sorting" },
  { apt: "SI & CI",                         dsa: "HashMap" },
  { apt: "Probability",                     dsa: "Stack & Queue" },
  { apt: "Permutation & Combination",       dsa: "Mixed Coding" },
  { apt: "Full Mock Tests",                 dsa: "Revision Only" },
];

function getTopics(day, totalDays) {
  if (!totalDays) return { apt: "", dsa: "" };
  // Last phase (mock tests/revision) always gets the final ~10% of days, min 1 day
  const revisionDays = Math.max(1, Math.round(totalDays * 0.1));
  const coreDays = totalDays - revisionDays;
  const coreCutoff = totalDays - revisionDays;

  if (day > coreCutoff) return TOPIC_PHASES[TOPIC_PHASES.length - 1];

  const corePhases = TOPIC_PHASES.length - 1;
  const perPhase = Math.max(1, Math.ceil(coreDays / corePhases));
  const phaseIdx = Math.min(corePhases - 1, Math.floor((day - 1) / perPhase));
  return TOPIC_PHASES[phaseIdx];
}

const TYPE_LABELS = { dsa: "DSA", apt: "Aptitude", reason: "Reasoning", eng: "English", tcs: "TCS", break: "Break", study: "Study" };

export default function TCSTracker() {
  const { user } = useAuth();
  const [activeDay, setActiveDay] = useState(1);
  const [progress, setProgress] = useState({});
  const [schedule, setSchedule] = useState([]);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);
  const [notes, setNotes] = useState({});
  const [notesSaving, setNotesSaving] = useState(false);
  const [totalDays, setTotalDays] = useState(30);

  useEffect(() => {
    const load = async () => {
      const setupSnap = await getDoc(doc(db, "user_setup", user.uid));
      if (setupSnap.exists()) {
        setSchedule(setupSnap.data().schedule || []);
        setTotalDays(setupSnap.data().totalDays || 30);
      }

      const progSnap = await getDoc(doc(db, "tcs_progress", user.uid));
      if (progSnap.exists()) setProgress(progSnap.data());

      const notesSnap = await getDoc(doc(db, "tcs_notes", user.uid));
      if (notesSnap.exists()) setNotes(notesSnap.data());

      setLoading(false);
    };
    load();
  }, []);

  const toggle = async (day, idx) => {
    const key = `d${day}_${idx}`;
    const updated = { ...progress, [key]: !progress[key] };
    setProgress(updated);
    setSaving(true);
    await setDoc(doc(db, "tcs_progress", user.uid), updated);
    setSaving(false);
    if (!progress[key]) toast.success("Task done! 🔥");
  };

  const dayDone = (day) =>
    schedule.reduce((acc, _, i) => acc + (progress[`d${day}_${i}`] ? 1 : 0), 0);

  const currentDayDone = dayDone(activeDay);
  const pct = schedule.length ? Math.round((currentDayDone / schedule.length) * 100) : 0;
  const topics = getTopics(activeDay, totalDays);

  const completedTasks = schedule.filter((slot, i) => slot.type !== "break" && progress[`d${activeDay}_${i}`]);
  const missedTasks = schedule.filter((slot, i) => slot.type !== "break" && !progress[`d${activeDay}_${i}`]);

  const saveTimer = useRef(null);
  const handleNotesChange = (val) => {
    const updated = { ...notes, [`d${activeDay}`]: val };
    setNotes(updated);
    setNotesSaving(true);
    clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      await setDoc(doc(db, "tcs_notes", user.uid), updated);
      setNotesSaving(false);
    }, 800);
  };

  if (loading) return (
    <div className="app-layout">
      <Sidebar />
      <main className="main-content" style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ color: "var(--text2)" }}>Loading your schedule...</div>
      </main>
    </div>
  );

  if (!schedule.length) return (
    <div className="app-layout">
      <Sidebar />
      <main className="main-content" style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ fontSize: 48, marginBottom: 16 }}>⚙️</div>
          <h2>No schedule found</h2>
          <p style={{ color: "var(--text2)", marginTop: 8 }}>Go to <a href="/study-tracker/setup" style={{ color: "var(--accent2)" }}>Setup</a> to create your plan</p>
        </div>
      </main>
    </div>
  );

  return (
    <div className="app-layout">
      <Sidebar />
      <main className="main-content">
        <div className="page-header">
          <h1>🎯 TCS Prep Tracker</h1>
          <p>Your personalized {totalDays}-day schedule — mark each slot as you complete it</p>
        </div>

        <div className="day-selector">
          {Array.from({ length: totalDays }, (_, i) => i + 1).map(day => {
            const done = dayDone(day);
            const cls = day === activeDay ? "active" : done >= schedule.length ? "completed" : "";
            return (
              <button key={day} className={`day-btn ${cls}`} onClick={() => setActiveDay(day)}>
                Day {day}
              </button>
            );
          })}
        </div>

        <div className="day-progress">
          <h3>Day {activeDay} · {topics.apt} | DSA: {topics.dsa}</h3>
          <div className="progress-bar-bg">
            <div className="progress-bar-fill" style={{ width: `${pct}%` }} />
          </div>
          <div className="progress-text">{currentDayDone}/{schedule.length} slots done ({pct}%) {saving && "· saving..."}</div>
        </div>

        <div className="schedule-table">
          <div className="schedule-header">
            <span>Time</span><span>Task</span><span>Done</span><span>Category</span>
          </div>
          {schedule.map((slot, idx) => {
            const done = !!progress[`d${activeDay}_${idx}`];
            return (
              <div key={idx} className={`schedule-row ${slot.type === "break" ? "break-row" : ""} ${done ? "done" : ""}`}>
                <div className="time-cell">{slot.time}</div>
                <div className={`task-cell ${slot.type === "break" ? "break-t" : slot.type}`}>{slot.task}</div>
                <button className={`check-btn ${done ? "checked" : ""}`} onClick={() => toggle(activeDay, idx)}>
                  {done ? "✓" : ""}
                </button>
                <span className="topic-pill">{TYPE_LABELS[slot.type] || slot.type}</span>
              </div>
            );
          })}
        </div>

        {/* Today's Revision */}
        <div style={{ background: "var(--bg2)", border: "1px solid var(--border)", borderRadius: 14, padding: "20px", marginBottom: 24 }}>
          <div style={{ fontWeight: 600, fontSize: 15, marginBottom: 4 }}>📝 Day {activeDay} Revision</div>
          <div style={{ fontSize: 12, color: "var(--text2)", marginBottom: 16 }}>
            Everything you covered today — review before you sleep
          </div>

          {completedTasks.length > 0 ? (
            <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 16 }}>
              {completedTasks.map((slot, i) => (
                <div key={i} style={{
                  display: "flex", alignItems: "center", gap: 10,
                  padding: "8px 12px", borderRadius: 8, background: "rgba(16,185,129,0.06)"
                }}>
                  <span style={{ color: "var(--green)", fontSize: 14 }}>✅</span>
                  <span className={`task-cell ${slot.type}`} style={{ fontSize: 13 }}>{slot.task}</span>
                  <span className="topic-pill" style={{ marginLeft: "auto" }}>{TYPE_LABELS[slot.type] || slot.type}</span>
                </div>
              ))}
            </div>
          ) : (
            <div style={{ fontSize: 13, color: "var(--text2)", marginBottom: 16, fontStyle: "italic" }}>
              Nothing marked done yet today — complete tasks above and they'll show here.
            </div>
          )}

          {missedTasks.length > 0 && (
            <div style={{ marginBottom: 16 }}>
              <div style={{ fontSize: 12, color: "var(--red)", fontWeight: 600, marginBottom: 6 }}>⚠️ Still pending ({missedTasks.length})</div>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                {missedTasks.map((slot, i) => (
                  <span key={i} style={{ fontSize: 11, padding: "3px 10px", borderRadius: 20, background: "rgba(239,68,68,0.1)", color: "#f87171" }}>
                    {slot.task}
                  </span>
                ))}
              </div>
            </div>
          )}

          <label style={{ display: "block", fontSize: 12, color: "var(--text2)", marginBottom: 6, fontWeight: 500 }}>
            What did you learn / struggle with today?
          </label>
          <textarea
            value={notes[`d${activeDay}`] || ""}
            onChange={(e) => handleNotesChange(e.target.value)}
            placeholder="e.g. Solved 2 DSA problems on arrays, struggled with sliding window. Need to revise SI & CI formulas again..."
            rows={4}
            style={{
              width: "100%", background: "var(--bg3)", border: "1px solid var(--border)",
              borderRadius: 10, padding: "12px 14px", color: "var(--text)",
              fontFamily: "Space Grotesk, sans-serif", fontSize: 13, outline: "none", resize: "vertical"
            }}
          />
          <div style={{ fontSize: 11, color: "var(--text2)", marginTop: 6 }}>
            {notesSaving ? "Saving..." : "Auto-saved"}
          </div>
        </div>

        <div style={{ background: "var(--bg2)", border: "1px solid var(--border)", borderRadius: 14, padding: "16px 20px" }}>
          <div style={{ fontWeight: 600, marginBottom: 10, fontSize: 14 }}>📊 Daily Targets</div>
          <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
            {["3 DSA Problems", "30 Aptitude Qs", "20 Reasoning Qs", "15 English Qs", "15 min Formula Rev"].map(t => (
              <span key={t} style={{ fontSize: 12, padding: "4px 12px", borderRadius: 20, background: "rgba(16,185,129,0.1)", color: "#34d399", fontWeight: 600 }}>✅ {t}</span>
            ))}
          </div>
        </div>
        <Footer />
      </main>
    </div>
  );
}
