import { useState } from "react";
import { useAuth } from "../context/AuthContext";
import { db } from "../firebase";
import { doc, setDoc } from "firebase/firestore";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";

function addMinutes(base, mins) {
  const [h, m] = base.split(":").map(Number);
  const total = h * 60 + m + mins;
  const nh = Math.floor(total / 60) % 24;
  const nm = total % 60;
  const period = nh >= 12 ? "PM" : "AM";
  const displayH = nh % 12 === 0 ? 12 : nh % 12;
  const displayM = nm.toString().padStart(2, "0");
  return { time: `${displayH}:${displayM} ${period}`, totalMins: total };
}

function formatSlot(startMins, endMins) {
  const fmt = (t) => {
    const h = Math.floor(t / 60) % 24;
    const m = t % 60;
    const period = h >= 12 ? "PM" : "AM";
    const dh = h % 12 === 0 ? 12 : h % 12;
    return `${dh}:${m.toString().padStart(2, "0")} ${period}`;
  };
  return `${fmt(startMins)} – ${fmt(endMins)}`;
}

function generateTCSSchedule(startHour, startMin) {
  let cursor = startHour * 60 + startMin;
  const slots = [
    { task: "Warm Up / Lunch Break", type: "break", mins: 60 },
    { task: "DSA Problem 1", type: "dsa", mins: 60 },
    { task: "DSA Problem 2 & 3", type: "dsa", mins: 60 },
    { task: "Snack Break", type: "break", mins: 30 },
    { task: "Aptitude Topic Study", type: "apt", mins: 60 },
    { task: "Aptitude Questions (30+)", type: "apt", mins: 60 },
    { task: "Dinner Break", type: "break", mins: 60 },
    { task: "Reasoning Topic", type: "reason", mins: 60 },
    { task: "Reasoning Questions", type: "reason", mins: 30 },
    { task: "Short Break", type: "break", mins: 30 },
    { task: "TCS Practice Set", type: "tcs", mins: 60 },
    { task: "Verbal English", type: "eng", mins: 60 },
    { task: "Formula Revision", type: "apt", mins: 30 },
    { task: "Free Time / Sleep Prep", type: "break", mins: 60 },
  ];
  return slots.map(s => {
    const start = cursor;
    const end = cursor + s.mins;
    cursor = end;
    return { ...s, time: formatSlot(start, end) };
  });
}

function generateGeneralSchedule(startHour, startMin, hours) {
  let cursor = startHour * 60 + startMin;
  const totalMins = hours * 60;
  const studyBlock = Math.floor((totalMins * 0.8) / 4); // 4 study blocks
  const breakBlock = Math.floor((totalMins * 0.2) / 2);

  const slots = [
    { task: "Study Block 1", type: "study", mins: studyBlock },
    { task: "Short Break", type: "break", mins: breakBlock },
    { task: "Study Block 2", type: "study", mins: studyBlock },
    { task: "Short Break", type: "break", mins: breakBlock },
    { task: "Study Block 3", type: "study", mins: studyBlock },
    { task: "Study Block 4", type: "study", mins: studyBlock },
  ];
  return slots.map(s => {
    const start = cursor;
    const end = cursor + s.mins;
    cursor = end;
    return { ...s, time: formatSlot(start, end) };
  });
}

export default function Setup() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [step, setStep] = useState(1);
  const [examType, setExamType] = useState("");
  const [startTime, setStartTime] = useState("14:00");
  const [hours, setHours] = useState(8);
  const [totalDays, setTotalDays] = useState(30);
  const [loading, setLoading] = useState(false);

  const handleFinish = async () => {
    setLoading(true);
    const [sh, sm] = startTime.split(":").map(Number);
    const schedule = examType === "tcs"
      ? generateTCSSchedule(sh, sm)
      : generateGeneralSchedule(sh, sm, hours);

    await setDoc(doc(db, "user_setup", user.uid), {
      examType,
      startTime,
      hours,
      totalDays,
      schedule,
      createdAt: Date.now()
    });
    toast.success("Plan ready! Let's go 🔥");
    navigate(examType === "tcs" ? "/tcs" : "/general");
    setLoading(false);
  };

  return (
    <div className="auth-page" style={{ background: "radial-gradient(ellipse at 40% 30%, #1e1b4b 0%, #0a0f1e 60%)" }}>
      <div className="auth-card" style={{ maxWidth: 480 }}>
        <div className="auth-logo">
          <h1>StudyTrack 🎯</h1>
          <p>Let's build your personal study plan</p>
        </div>

        {/* Step indicators */}
        <div style={{ display: "flex", gap: 8, marginBottom: 28, justifyContent: "center" }}>
          {[1, 2, 3].map(s => (
            <div key={s} style={{
              width: 32, height: 4, borderRadius: 2,
              background: s <= step ? "var(--accent)" : "var(--border)",
              transition: "background 0.3s"
            }} />
          ))}
        </div>

        {step === 1 && (
          <>
            <h2 style={{ marginBottom: 6 }}>What are you preparing for?</h2>
            <p style={{ color: "var(--text2)", fontSize: 13, marginBottom: 24 }}>We'll build a schedule based on this</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {[
                { key: "tcs", icon: "🎯", title: "TCS NQT / Campus Hiring", desc: "30-day structured plan — DSA, Aptitude, Reasoning, English" },
                { key: "general", icon: "📚", title: "General Study Tracker", desc: "Custom schedule for any subject or exam" },
              ].map(opt => (
                <div
                  key={opt.key}
                  onClick={() => setExamType(opt.key)}
                  style={{
                    padding: "16px 18px", borderRadius: 12, cursor: "pointer",
                    border: `2px solid ${examType === opt.key ? "var(--accent)" : "var(--border)"}`,
                    background: examType === opt.key ? "rgba(99,102,241,0.1)" : "var(--bg3)",
                    transition: "all 0.2s"
                  }}
                >
                  <div style={{ fontWeight: 600, fontSize: 15 }}>{opt.icon} {opt.title}</div>
                  <div style={{ fontSize: 12, color: "var(--text2)", marginTop: 4 }}>{opt.desc}</div>
                </div>
              ))}
            </div>
            <button
              className="btn btn-primary" style={{ marginTop: 24 }}
              onClick={() => examType && setStep(2)}
              disabled={!examType}
            >Next →</button>
          </>
        )}

        {step === 2 && (
          <>
            <h2 style={{ marginBottom: 6 }}>When do you start studying?</h2>
            <p style={{ color: "var(--text2)", fontSize: 13, marginBottom: 24 }}>We'll generate your time slots from this</p>
            <div className="form-group">
              <label>Study Start Time</label>
              <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} />
            </div>
            <div className="form-group">
              <label>How many days is your plan?</label>
              <input
                type="number"
                min={1}
                max={365}
                value={totalDays}
                onChange={e => setTotalDays(Math.max(1, Math.min(365, Number(e.target.value) || 1)))}
                placeholder="e.g. 30"
              />
              <div style={{ fontSize: 11, color: "var(--text2)", marginTop: 6 }}>
                Enter any number — your topic plan will spread evenly across these days
              </div>
            </div>
            {examType === "general" && (
              <div className="form-group">
                <label>How many hours per day?</label>
                <select value={hours} onChange={e => setHours(Number(e.target.value))}
                  style={{ width: "100%", background: "var(--bg3)", border: "1px solid var(--border)", borderRadius: 10, padding: "12px 16px", color: "var(--text)", fontFamily: "Space Grotesk", fontSize: 14, outline: "none" }}>
                  {[4,5,6,7,8,9,10].map(h => <option key={h} value={h}>{h} hours</option>)}
                </select>
              </div>
            )}
            <div style={{ display: "flex", gap: 10, marginTop: 24 }}>
              <button className="btn" style={{ background: "var(--bg3)", border: "1px solid var(--border)", color: "var(--text2)" }} onClick={() => setStep(1)}>← Back</button>
              <button className="btn btn-primary" onClick={() => setStep(3)}>Next →</button>
            </div>
          </>
        )}

        {step === 3 && (
          <>
            <h2 style={{ marginBottom: 6 }}>Your plan is ready! 🔥</h2>
            <p style={{ color: "var(--text2)", fontSize: 13, marginBottom: 24 }}>{totalDays}-day plan — here's a preview of your daily schedule</p>
            <div style={{ background: "var(--bg3)", borderRadius: 12, padding: 16, maxHeight: 280, overflowY: "auto", marginBottom: 20 }}>
              {(() => {
                const [sh, sm] = startTime.split(":").map(Number);
                const schedule = examType === "tcs"
                  ? generateTCSSchedule(sh, sm)
                  : generateGeneralSchedule(sh, sm, hours);
                return schedule.map((slot, i) => (
                  <div key={i} style={{ display: "flex", gap: 12, padding: "8px 0", borderBottom: "1px solid var(--border)", alignItems: "center" }}>
                    <span style={{ fontSize: 11, color: "var(--text2)", fontFamily: "JetBrains Mono", minWidth: 140 }}>{slot.time}</span>
                    <span style={{ fontSize: 13, fontWeight: slot.type !== "break" ? 600 : 400, color: slot.type === "break" ? "var(--text2)" : "var(--text)" }}>{slot.task}</span>
                  </div>
                ));
              })()}
            </div>
            <div style={{ display: "flex", gap: 10 }}>
              <button className="btn" style={{ background: "var(--bg3)", border: "1px solid var(--border)", color: "var(--text2)" }} onClick={() => setStep(2)}>← Back</button>
              <button className="btn btn-primary" onClick={handleFinish} disabled={loading}>
                {loading ? "Setting up..." : "Start Tracking 🚀"}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
