import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { db } from "../firebase";
import { doc, getDoc } from "firebase/firestore";
import Sidebar from "../components/Sidebar";
import Footer from "../components/Footer";

export default function Dashboard() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [checking, setChecking] = useState(true);
  const [examType, setExamType] = useState(null);
  const [totalDays, setTotalDays] = useState(30);
  const name = user?.displayName?.split(" ")[0] || "there";
  const hour = new Date().getHours();
  const greeting = hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening";

  useEffect(() => {
    getDoc(doc(db, "user_setup", user.uid)).then(snap => {
      if (!snap.exists()) navigate("/setup");
      else {
        setExamType(snap.data().examType || "general");
        setTotalDays(snap.data().totalDays || 30);
        setChecking(false);
      }
    });
  }, []);

  if (checking) return (
    <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: "var(--bg)", color: "var(--text2)" }}>
      Loading...
    </div>
  );

  return (
    <div className="app-layout">
      <Sidebar />
      <main className="main-content">
        <div className="page-header" style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", flexWrap: "wrap", gap: 16 }}>
          <div>
            <h1>{greeting}, {name} 👋</h1>
            <p>What are you working on today?</p>
          </div>
          <div
            onClick={() => navigate("/setup")}
            style={{
              display: "flex", alignItems: "center", gap: 10,
              background: "var(--bg2)", border: "1px solid var(--border)",
              borderRadius: 999, padding: "8px 16px", cursor: "pointer",
              transition: "border-color 0.2s"
            }}
            title="Click to switch plan or update timings"
          >
            <span style={{ fontSize: 13, color: "var(--text2)" }}>Mode:</span>
            <span style={{
              fontSize: 13, fontWeight: 700,
              color: examType === "tcs" ? "#818cf8" : "#34d399"
            }}>
              {examType === "tcs" ? "🎯 TCS Prep" : "📚 General Study"}
            </span>
            <span style={{ fontSize: 11, color: "var(--text2)" }}>· switch ⟳</span>
          </div>
        </div>

        <div className="stats-grid">
          <div className="stat-card">
            <div className="stat-label">STREAK</div>
            <div className="stat-value" style={{ color: "#f59e0b" }}>0 🔥</div>
            <div className="stat-sub">days in a row</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">{examType === "tcs" ? "TCS PROGRESS" : "PLAN PROGRESS"}</div>
            <div className="stat-value" style={{ color: "#6366f1" }}>Day 1</div>
            <div className="stat-sub">of {totalDays} days</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">TASKS TODAY</div>
            <div className="stat-value" style={{ color: "#10b981" }}>0/14</div>
            <div className="stat-sub">completed</div>
          </div>
          <div className="stat-card">
            <div className="stat-label">OVERALL</div>
            <div className="stat-value" style={{ color: "#a855f7" }}>0%</div>
            <div className="stat-sub">plan completed</div>
          </div>
        </div>

        <div className="cards-grid">
          <Link to="/tcs" className="feature-card" style={examType !== "tcs" ? { opacity: 0.5 } : { borderColor: "var(--accent)" }}>
            <div className="card-icon" style={{ background: "rgba(99,102,241,0.15)" }}>🎯</div>
            <h3>TCS Prep Tracker {examType === "tcs" && <span style={{ fontSize: 11, color: "#818cf8" }}>· active</span>}</h3>
            <p>Your personalized {totalDays}-day plan with daily time slots based on your schedule.</p>
            <span className="badge" style={{ background: "rgba(99,102,241,0.15)", color: "#818cf8" }}>{examType === "tcs" ? totalDays : 30} Days</span>
          </Link>
          <Link to="/general" className="feature-card" style={examType !== "general" ? { opacity: 0.5 } : { borderColor: "var(--green)" }}>
            <div className="card-icon" style={{ background: "rgba(16,185,129,0.15)" }}>📚</div>
            <h3>General Study Tracker {examType === "general" && <span style={{ fontSize: 11, color: "#34d399" }}>· active</span>}</h3>
            <p>Add any task, assign a category and deadline, mark them off as you go.</p>
            <span className="badge" style={{ background: "rgba(16,185,129,0.15)", color: "#34d399" }}>Custom</span>
          </Link>
          <Link to="/excel-planner" className="feature-card">
            <div className="card-icon" style={{ background: "rgba(245,158,11,0.15)" }}>📊</div>
            <h3>Excel Plan Generator</h3>
            <p>Upload your Excel timetable — system reads and tracks your progress.</p>
            <span className="badge" style={{ background: "rgba(245,158,11,0.15)", color: "#fbbf24" }}>Upload</span>
          </Link>
          <Link to="/setup" className="feature-card">
            <div className="card-icon" style={{ background: "rgba(239,68,68,0.15)" }}>⚙️</div>
            <h3>Update My Schedule</h3>
            <p>Change your study start time or switch between TCS and General plan.</p>
            <span className="badge" style={{ background: "rgba(239,68,68,0.15)", color: "#f87171" }}>Settings</span>
          </Link>
        </div>

        <div style={{
          marginTop: 28, background: "rgba(239,68,68,0.08)",
          border: "1px solid rgba(239,68,68,0.25)", borderRadius: 14, padding: "16px 20px"
        }}>
          <div style={{ fontWeight: 600, marginBottom: 6 }}>🚨 Non-Negotiables</div>
          <div style={{ fontSize: 13, color: "#94a3b8", lineHeight: 1.8 }}>
            ❌ No portfolio changes &nbsp;·&nbsp; ❌ No new projects &nbsp;·&nbsp; ❌ No random frameworks &nbsp;·&nbsp; ❌ No "I'll start tomorrow"<br />
            ✅ TCS &nbsp;·&nbsp; ✅ Aptitude &nbsp;·&nbsp; ✅ Coding &nbsp;·&nbsp; ✅ Mock Tests
          </div>
        </div>
        <Footer />
      </main>
    </div>
  );
}
